package com.spinplayer.app;
import org.schabi.newpipe.extractor.downloader.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.GZIPInputStream;
public class NetDownloader extends Downloader {
 public static final String UA="Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Mobile Safari/537.36";
 public static HttpURLConnection connect(String address)throws IOException{URL url=new URL(address);if(!"https".equals(url.getProtocol()))throw new IOException("Поддерживаются только HTTPS-ссылки");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent",UA);c.setRequestProperty("Accept-Encoding","identity");return c;}
 @Override public Response execute(Request request)throws IOException{HttpURLConnection c=connect(request.url());try{c.setRequestMethod(request.httpMethod());for(Map.Entry<String,List<String>> h:request.headers().entrySet())for(String v:h.getValue())c.addRequestProperty(h.getKey(),v);byte[] body=request.dataToSend();if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body);}}int status=c.getResponseCode();InputStream in=status>=400?c.getErrorStream():c.getInputStream();String response="";if(in!=null){if("gzip".equalsIgnoreCase(c.getContentEncoding()))in=new GZIPInputStream(in);try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=input.read(b))!=-1){if(out.size()+n>24*1024*1024)throw new IOException("Ответ источника слишком большой");out.write(b,0,n);}response=new String(out.toByteArray(),StandardCharsets.UTF_8);}}return new Response(status,c.getResponseMessage(),c.getHeaderFields(),response,c.getURL().toString());}finally{c.disconnect();}}
}
